/** The React and Vue policy plus **one** widening: `style-src 'unsafe-inline'`.
 *
 * `StyleSheet.create` on the web is react-native-web's runtime style engine: it
 * writes the app's styles into a `<style>` element it creates, and it has no
 * nonce support. That is the injection the React scaffold avoids by using a CSS
 * file; a React Native screen has no CSS file to use. Scripts stay strict — no
 * `'unsafe-inline'` and no `'unsafe-eval'` in `script-src`, which the baseline's
 * `default-src 'self'` governs. */
const csp = {
  "style-src": ["'self'", "'unsafe-inline'"],
  "img-src": ["'self'", "data:"],
  "font-src": ["'self'", "data:"],
  "connect-src": ["'self'"],
  "object-src": ["'none'"],
  "base-uri": ["'self'"],
  "frame-ancestors": ["'none'"],
};

