/** The builds offered beside the web bundle. The build type picks the Gradle
 * task and so where the APK lands; the environment is this module's settings.
 * A setting left blank is left out, so the build falls back to the server's own
 * environment.
 *
 * iOS is two targets rather than one with a build type, because what they
 * leave differs in kind: a simulator build is an unsigned `.app` directory,
 * zipped, and a device build a signed `.ipa`. */
function targets({
  android_home = "",
  java_home = "",
  use_pod_dir,
  pod_dir = "",
  use_asc,
  asc_issuer_id = "",
  asc_key_id = "",
  asc_key = "",
  ios_distribution_identity = "",
}) {
  const on = (checkbox) => checkbox === true || checkbox === "true";
  const useAsc = on(use_asc);
  const podDir = on(use_pod_dir) ? { FELDSPAR_POD_DIR: pod_dir } : {};
  // The App Store Connect API key, for the build and the operation alike.
  const ascEnv = useAsc
    ? {
        FELDSPAR_ASC_ISSUER_ID: asc_issuer_id,
        FELDSPAR_ASC_KEY_ID: asc_key_id,
        FELDSPAR_ASC_KEY: asc_key,
        FELDSPAR_IOS_IDENTITY: ios_distribution_identity,
      }
    : {};
  return {
    android: {
      label: "Android app",
      // One script per build type and package; each leaves its result at a
      // fixed path outside `android/`, which `prebuild --clean` deletes.
      command: "npm run build:android:{{ build_type }}-{{ package_format }}",
      artifact:
        "{{ project }}/android-output/app-{{ build_type }}.{{ package_format }}",
      options: android_options,
      operations: {
        generate_keystore: {
          label: "Generate a keystore",
          description:
            "Creates a new signing key in the file store (keys/<subdomain>-release.p12) and fills " +
            "in the settings above. A blank password gets a strong one, shown once.",
          showIf: { build_type: "release", own_keystore: true },
          run: generateKeystore,
        },
      },
      env: {
        ANDROID_HOME: android_home,
        JAVA_HOME: java_home,
        // The keystore password reaches Gradle here, never through a file in
        // the project (`app.config.js` reads it from the environment).
        FELDSPAR_KEYSTORE_PASSWORD: "{{ keystore_password }}",
      },
      // Checked before a build starts and shown on the button: a server without
      // the toolchain says so at once, instead of Gradle saying it minutes into a
      // build. Met by the settings above, or by the server's own environment.
      requires: [
        {
          env: "ANDROID_HOME",
          directory: true,
          hint: "Set the Android SDK directory under Settings → Modules → React Native.",
        },
        {
          env: "JAVA_HOME",
          directory: true,
          hint: "Set the JDK directory under Settings → Modules → React Native.",
        },
      ],
    },
    ios: {
      label: "iOS app",
      command: "npm run build:ios:device",
      artifact: "{{ project }}/ios-output/app.ipa",
      options: ios_options,
      // Offered for an uploaded profile whether or not the API is switched on,
      // so the button is there to find; switched off, it says where to turn it on.
      operations: {
        generate_profile: {
          label: "Generate a provisioning profile",
          description:
            "Creates or reuses an App Store profile for this app's App ID through App Store Connect " +
            "(API key under Settings → Modules → React Native), stores it in the file store " +
            "(keys/<subdomain>-app-store-<date>.mobileprovision) and selects it above.",
          showIf: { ios_profile_source: "own" },
          run: (ctx) => {
            if (!useAsc)
              throw new Error(
                'The App Store Connect API is switched off. Tick "Use the App Store Connect API" ' +
                  "under Settings → Modules → React Native and fill in its key, or upload a profile " +
                  "made in Apple's developer portal instead.",
              );
            return generateProfileOperation(ctx, ascEnv);
          },
        },
      },
      // Environment variables for the build: the CocoaPods directory, and,
      // if the App Store Connect API is on, its key for generating profiles.
      env: { ...podDir, ...ascEnv },
      requires: IOS_REQUIRES,
    },
    ios_simulator: {
      label: "iOS simulator app",
      command: "npm run build:ios:simulator",
      artifact: "{{ project }}/ios-output/app-simulator.zip",
      options: ios_simulator_options,
      env: podDir,
      requires: IOS_REQUIRES,
    },
  };
}

/** Generate a signing keystore for the application: an RSA 2048 key with a
 * self-signed certificate valid for 10,000 days (Google Play wants validity
 * past 2033), as PKCS12, which Gradle and Java's `keytool` read. Pure
 * JavaScript (node-forge), so it needs no JDK and no permission to run one.
 *
 * Saltcorn writes the file into the application's store — refusing to replace
 * an existing one — and saves the settings; this only makes them. The alias
 * and password are the ones in the form, or `upload` and a random password. */
function generateKeystore(ctx) {
  const forge = require("node-forge");
  const settings = ctx.settings || {};
  const app = ctx.app || {};
  const alias = String(settings.keystore_alias || "").trim() || "upload";
  let password = String(settings.keystore_password || "");
  const generated = password === "";
  if (generated) {
    password = forge.util
      .encode64(forge.random.getBytesSync(18))
      .replace(/[+/=]/g, "x");
  }
  if (password.length < 6) {
    throw new Error(
      "A keystore password needs at least 6 characters; Java refuses shorter ones."
    );
  }

  const keys = forge.pki.rsa.generateKeyPair({ bits: 2048 });
  const cert = forge.pki.createCertificate();
  cert.publicKey = keys.publicKey;
  // Positive, and random so two keys are never confused for each other.
  cert.serialNumber = `01${forge.util.bytesToHex(
    forge.random.getBytesSync(15)
  )}`;
  cert.validity.notBefore = new Date();
  cert.validity.notAfter = new Date(Date.now() + 10000 * 24 * 60 * 60 * 1000);
  const subject = [
    { name: "commonName", value: String(app.name || app.subdomain || "App") },
  ];
  cert.setSubject(subject);
  cert.setIssuer(subject);
  cert.sign(keys.privateKey, forge.md.sha256.create());
  const p12 = forge.pkcs12.toPkcs12Asn1(keys.privateKey, [cert], password, {
    algorithm: "3des",
    friendlyName: alias,
    generateLocalKeyId: true,
  });

  const path = `keys/${keyFileName(app)}-release.p12`;
  const keep =
    "Keep a copy of the keystore and its password somewhere safe: an app signed with it " +
    "can only be updated with it.";
  return {
    files: [
      { path, base64: forge.util.encode64(forge.asn1.toDer(p12).getBytes()) },
    ],
    settings: {
      own_keystore: true,
      keystore_file: path,
      keystore_alias: alias,
      keystore_password: password,
    },
    message: generated
      ? `Generated ${path} with the key "${alias}". Its password, shown only now: ${password} — ${keep}`
      : `Generated ${path} with the key "${alias}" and the password you entered. ${keep}`,
  };
}

/** The app's subdomain as the start of a file name under `keys/`. */
const keyFileName = (app) =>
  String(app.subdomain || "app")
    .toLowerCase()
    .replace(/[^a-z0-9_-]/g, "-");

/** Generate an App Store provisioning profile for the application through the
 * App Store Connect API, without building: the same code a "generate" build
 * runs (`ios/profile-generator.cjs`). The worker cannot see the build Mac's
 * keychain, so the certificate is picked from App Store Connect alone; a build
 * on a Mac without its private key still stops with a clear message.
 *
 * Saltcorn writes the file into the store and saves the settings. The name
 * carries the date and time, because a store file is never replaced and a
 * profile is renewed every year. */
async function generateProfileOperation(ctx, ascEnv) {
  const { IosProfileGenerator } = require("./ios/profile-generator.cjs");
  const app = ctx.app || {};
  const now = new Date();
  const generator = new IosProfileGenerator(ascEnv, { now, log: () => {} });
  const profile = await generator.generate(iosBundleId(appIdFor(ctx)), null);
  // 2026-10-08T14:30… → 20261008-1430
  const stamp = now
    .toISOString()
    .slice(0, 16)
    .replace(/[-:]/g, "")
    .replace("T", "-");
  const path = `keys/${keyFileName(app)}-app-store-${stamp}.mobileprovision`;
  const expires = String(profile.expires || "").slice(0, 10);
  return {
    files: [{ path, base64: profile.content }],
    settings: { ios_profile_source: "own", ios_profile: path },
    message:
      `Stored the provisioning profile "${profile.name}" in ${path}` +
      (expires ? `, valid until ${expires}` : "") +
      `. It is for the certificate ${profile.certificate.name}: the Mac that builds the app needs ` +
      "that certificate's private key in its keychain.",
  };
}

/** The builder agent's system prompt: its role and this platform. */
const builder_prompt = `You build the \`{{ app }}\` application, an Expo (React Native) project \
served on the web at the \`{{ subdomain }}\` subdomain and built into Android and iOS apps. Its source \
is in the \`{{ store }}\` file store under \`{{ root }}\`, and your file tools are scoped to \
exactly that directory.

Four conventions of this framework: \`src/feldspar/\` is generated from the application's own \
API — its typed client and hooks are rewritten on every build, so read it to learn what data is \
available but never edit it; the application's data is reached through that client, never by \
talking to a database; screens are components under \`src/screens/\`, registered in \
\`src/routes.tsx\`; and screens use React Native's components and \`StyleSheet\` only — no DOM \
elements and no CSS files — so that the same source runs on the web and on a phone.`;

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

/** A path under the project. `""` is the project root. */
const at = (dir, name) => (dir ? `${dir}/${name}` : name);

/** The row/insert/update types `hooks.ts` itself names — what it *uses*, which
 * is not what it re-exports; an unused type import fails `noUnusedLocals`. */
function usedRowTypes(table) {
  const used = [`${table.pascal}Row`];
  if (table.ops.create) used.push(`${table.pascal}Insert`);
  if (table.ops.update && table.pk) used.push(`${table.pascal}Update`);
  return used;
}

/** The named imports one file needs from a module, in a stable order. */
function importLine(names, from) {
  return names.length ? `import { ${names.join(", ")} } from "${from}";\n` : "";
}

// ---------------------------------------------------------------------------
// The generated runtime — React Native's half of `src/feldspar/`
// ---------------------------------------------------------------------------

/** `hooks.ts`: the React scaffold's hooks, unchanged in shape — a screen here
 * and a page in a React app read their data the same way. Hooks are React's, not
 * the DOM's, so nothing in this file is web-specific. */
function hooksTs(ctx) {
  const rowTypes = ctx.tables.flatMap(usedRowTypes);
  let out = GENERATED;
  out += `
import { useCallback, useEffect, useState, useSyncExternalStore } from "react";
import { Platform } from "react-native";

import { createClient, type ApiClient } from "./client";
import { APP_URL } from "./config";
`;
  if (rowTypes.length)
    out += `import type { ${rowTypes.join(", ")} } from "./client";\n`;
  out += `
/**
 * The app's typed API client. Endpoint paths already include the API mount.
 *
 * On the web the page's own origin is the application, so requests stay
 * relative. On a phone there is no page: they go to the application's URL.
 */
export const api: ApiClient = createClient({
  baseUrl: Platform.OS === "web" ? "" : APP_URL,
});

/** The state of one read: data, plus what is happening to it. */
export type Query<T> = {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  /** Re-run this query (and any other on the same table). */
  refresh: () => void;
};

/** The state of one write. */
export type Mutation<A> = {
  run: (arg: A) => Promise<void>;
  pending: boolean;
  error: Error | undefined;
};

// One version counter per table: every read subscribes to its table, every
// write bumps it.
const versions = new Map<string, number>();
const listeners = new Map<string, Set<() => void>>();

function versionOf(table: string): number {
  return versions.get(table) ?? 0;
}

function subscribe(table: string, listener: () => void): () => void {
  const set = listeners.get(table) ?? new Set<() => void>();
  listeners.set(table, set);
  set.add(listener);
  return () => set.delete(listener);
}

/** Discard what is cached for \`table\`, re-running every query over it. */
export function invalidate(table: string): void {
  versions.set(table, versionOf(table) + 1);
  listeners.get(table)?.forEach((l) => l());
}

/**
 * Read something from the API, cached under \`table\` and re-run whenever
 * anything writes to that table. Exported so a custom endpoint can join the
 * same cache.
 */
export function useQuery<T>(table: string, load: () => Promise<T>): Query<T> {
  const version = useSyncExternalStore(
    (cb) => subscribe(table, cb),
    () => versionOf(table),
    () => 0,
  );
  const [state, setState] = useState<{
    data: T | undefined;
    error: Error | undefined;
    loading: boolean;
  }>({ data: undefined, error: undefined, loading: true });

  useEffect(() => {
    let cancelled = false;
    setState((s) => ({ ...s, loading: true }));
    load().then(
      (data) => !cancelled && setState({ data, error: undefined, loading: false }),
      (e: unknown) =>
        !cancelled &&
        setState({
          data: undefined,
          error: e instanceof Error ? e : new Error(String(e)),
          loading: false,
        }),
    );
    return () => {
      cancelled = true;
    };
    // \`load\` is rebuilt every render; the table's version is what changes the answer.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [table, version]);

  return { ...state, refresh: () => invalidate(table) };
}

/**
 * Write through \`fn\`, then invalidate \`table\` so every query over it re-runs.
 * Exported for the same reason as \`useQuery\`.
 */
export function useMutation<A>(table: string, fn: (arg: A) => Promise<unknown>): Mutation<A> {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<Error | undefined>(undefined);
  const run = useCallback(
    async (arg: A) => {
      setPending(true);
      setError(undefined);
      try {
        await fn(arg);
        invalidate(table);
      } catch (e: unknown) {
        setError(e instanceof Error ? e : new Error(String(e)));
      } finally {
        setPending(false);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [table],
  );
  return { run, pending, error };
}
`;
  for (const table of ctx.tables) out += `\n${tableHooks(table)}`;
  return out;
}

/** One table's hooks, over that table's own object on the client. The
 * row-addressed ones follow the endpoints: the API projects them only for a
 * table with a single-column key. */
function tableHooks(table) {
  const { name, pascal, client, pk, pk_ts_type: key } = table;
  const exported = [`type ${pascal}Row`];
  if (table.ops.create || table.ops.update) {
    exported.push(`type ${pascal}Insert`, `type ${pascal}Update`);
  }

  let out = `// --- ${name} ---

export { ${exported.join(", ")} } from "./client";

/** Every row of \`${name}\`, re-fetched when anything writes to it. */
export function use${pascal}(): Query<${pascal}Row[]> {
  return useQuery("${name}", () => api.${client}.list());
}
`;
  if (table.ops.create) {
    out += `
/** Insert a row into \`${name}\`. */
export function useCreate${pascal}(): Mutation<${pascal}Insert> {
  return useMutation("${name}", (row) => api.${client}.create(row));
}
`;
  }
  if (pk) {
    out += `
/** One row of \`${name}\`, selected from the list by its primary key. */
export function use${pascal}Row(id: ${key}): Query<${pascal}Row | undefined> {
  const rows = use${pascal}();
  return { ...rows, data: rows.data?.find((r) => r.${pk} === id) };
}
`;
    if (table.ops.update) {
      out += `
/** Change a row of \`${name}\`. */
export function useUpdate${pascal}(): Mutation<{ id: ${key}; row: ${pascal}Update }> {
  return useMutation("${name}", ({ id, row }) => api.${client}.update(id, row));
}
`;
    }
    if (table.ops.delete) {
      out += `
/** Delete a row of \`${name}\`. */
export function useDelete${pascal}(): Mutation<${key}> {
  return useMutation("${name}", (id) => api.${client}.delete(id));
}
`;
    }
  }
  return out;
}

/** `config.ts`: where the application is, for a client that is not a page on
 * it. Rewritten on every build, so a changed setting reaches the next APK. */
function configTs(ctx) {
  return `${GENERATED}
/**
 * Where a phone sends its API requests; on the web they stay relative to the
 * page. It is the application's "Server URL for the mobile app" setting, or its
 * own URL when that is blank. A phone cannot reach \`localhost\`: for an emulator
 * or a device on the LAN, set that setting (e.g. \`http://<subdomain>.10.0.2.2.nip.io:3032\`),
 * list the domain in the server's \`extra_base_domains\`, and build again.
 */
export const APP_URL = ${JSON.stringify(mobileUrl(ctx))};
`;
}

/** The generated directory's own README. */
function runtimeReadme(ctx) {
  const list = ctx.tables.length
    ? ctx.tables
        .map((t) => `- \`use${t.pascal}()\` — every row of \`${t.name}\``)
        .join("\n")
    : "- (this application exposes no tables yet)";
  return `# \`${ctx.runtime}\` — generated

Everything in this directory is written by Saltcorn and **rewritten on every
build**. Edits here are lost. It is generated from the \`${ctx.app.name}\`
application's own API, so adding a table or a column in the admin UI makes the
matching types and hooks exist at the next build.

| file | what it is |
|---|---|
| \`client.ts\` | the typed API client: one method per endpoint this application exposes |
| \`helper.ts\` | how a request is made and how a failure is reported — the same in every application |
| \`hooks.ts\` | React hooks over that client, one set per table |
| \`config.ts\` | the application's URL, which a phone sends its requests to |
| \`native.json\` | the native apps' settings (application and bundle ID, version, icon, build type, provisioning profile), which \`app.config.js\` reads |
| \`ios/build.cjs\` | the iOS builds: the \`build:ios:*\` scripts |
| \`ios/prebuild.cjs\` | \`app.config.js\`'s iOS checks and signing |
| \`ios/signing.cjs\` | reading the provisioning profile, shared by the two above |
| \`ios/profile-generator.cjs\` | generating a provisioning profile through the App Store Connect API |
| \`schema.sql\` | a description of this application's tables, for writing SQL against |
| \`SKILL.md\` | the half of the application that is *not* in this repository |

## The hooks

${list}

A write is a \`Mutation\`: call \`run\`, and every query over that table re-runs.

## The API is missing something I need

Add a custom SQL query to the application and it becomes a typed method on
\`client.ts\` at the next build:

\`\`\`sh
feldspar api add-query --app ${ctx.app.subdomain} --name recentPosts \\
  --sql "SELECT * FROM posts ORDER BY published DESC LIMIT :n"
\`\`\`
`;
}

// ---------------------------------------------------------------------------
// The project, written once
// ---------------------------------------------------------------------------

/** The project's `package.json`. Written once; the project's to change.
 *
 * All versions are from one Expo SDK (57), which pins the React Native and
 * React versions it was tested with; mixing SDKs breaks the build.
 *
 * Scripts:
 * - `build`: the web bundle Saltcorn serves.
 * - `build:android:<type>-<package>` (release/debug, apk/aab): `expo prebuild
 *   --clean` regenerates `android/`, Gradle builds it, and the result is copied
 *   to `android-output/app-<type>.<package>` for the server to pick up. Every
 *   build includes its JavaScript, so no Metro dev server is needed.
 *   `--no-daemon` so no Gradle daemon (about 1 GB) is left running on the server.
 * - `build:ios:<simulator|device>`: run `ios/build.cjs`. */
function packageJson(ctx) {
  const buildProperties = cleartext(ctx)
    ? `,\n    "expo-build-properties": "~57.0.22"`
    : "";
  return `{
  "name": "${ctx.name}",
  "private": true,
  "version": "0.1.0",
  "main": "index.ts",
  "scripts": {
    "start": "expo start",
    "build": "tsc --noEmit && expo export --platform web --output-dir dist",
    "typecheck": "tsc --noEmit",
${androidScripts()},
    "build:ios:simulator": "node ${ctx.runtime}/ios/build.cjs simulator",
    "build:ios:device": "node ${ctx.runtime}/ios/build.cjs device"
  },
  "dependencies": {
    "@expo/metro-runtime": "~57.0.16",
    "expo": "~57.0.25",
    "react": "19.2.3",
    "react-dom": "19.2.3",
    "react-native": "0.86.3",
    "react-native-web": "~0.21.0"${buildProperties}
  },
  "devDependencies": {
    "@expo/plist": "^0.8.1",
    "@types/react": "~19.2.2",
    "typescript": "~6.0.3"
  }
}
`;
}

/** The `build:android:<type>-<package>` scripts (see `packageJson`), as
 * `package.json` lines. A debug AAB is not offered in the form, but its script
 * exists: a release build switched back to debug keeps "aab" in its (then
 * hidden) package setting. */
function androidScripts() {
  const prebuild = "expo prebuild --platform android --clean --no-install";
  const lines = [];
  for (const type of ["release", "debug"]) {
    const Type = type[0].toUpperCase() + type.slice(1);
    for (const [pkg, task, dir] of [
      ["apk", `assemble${Type}`, "apk"],
      ["aab", `bundle${Type}`, "bundle"],
    ]) {
      const output = `app/build/outputs/${dir}/${type}/app-${type}.${pkg}`;
      lines.push(
        `    "build:android:${type}-${pkg}": "${prebuild} && cd android && ./gradlew ${task} ` +
          `--no-daemon && mkdir -p ../android-output && cp ${output} ../android-output/app-${type}.${pkg}"`
      );
    }
  }
  return lines.join(",\n");
}

/** Where the APK sends its requests: the `mobile_url` setting when the admin
 * gave one, the application's own URL otherwise. Without a trailing slash, since
 * the client appends paths that start with one. */
function mobileUrl(ctx) {
  const setting = ((ctx.settings || {}).mobile_url || "").trim();
  return (setting || ctx.app.url || "").replace(/\/+$/, "");
}

/** Whether the APK reaches its server over plain `http://` — a development
 * server. Android refuses cleartext traffic from a release build unless the app
 * says otherwise, so such an app says otherwise; one served over HTTPS does not
 * carry the permission it does not need. Decided when the project is written. */
const cleartext = (ctx) => /^http:/i.test(mobileUrl(ctx));

/** The native apps' ID: the "App ID" setting, else `com.feldspar.<subdomain>`
 * as Java package segments (lowercase letters, digits and `_`, starting with a
 * letter), which Android requires. iOS gets it through `iosBundleId`. */
function appIdFor(ctx) {
  const own = String((ctx.settings || {}).app_id || "").trim();
  if (own) return own;
  let segment = String((ctx.app || {}).subdomain || ctx.name || "app")
    .toLowerCase()
    .replace(/[^a-z0-9_]/g, "_");
  if (!/^[a-z]/.test(segment)) segment = `app_${segment}`;
  return `com.feldspar.${segment}`;
}

/** The Android application ID as an iOS bundle ID, which has `-` where Java
 * allows `_` and nothing else: `com.feldspar.my_app` → `com.feldspar.my-app`. */
const iosBundleId = (appId) => appId.replace(/_/g, "-");

/** A store-relative path as a path relative to the project directory, which
 * is what Expo resolves `icon` against. `null` for a path that climbs. */
function projectRelative(ctx, storePath) {
  const parts = String(storePath)
    .split("/")
    .filter((p) => p && p !== ".");
  if (parts.includes("..")) return null;
  const project = String(ctx.project || "")
    .split("/")
    .filter((p) => p && p !== ".");
  let common = 0;
  while (common < project.length && project[common] === parts[common]) common++;
  return [
    ...project.slice(common).map(() => ".."),
    ...parts.slice(common),
  ].join("/");
}

/** `native.json`: the APK's settings, rewritten on every build so a changed
 * setting reaches the next APK. Checked by `app.config.js` when the Android
 * project is written, not here: this is written by every web build too, which
 * a bad version must not fail. The keystore password is not in it: it reaches
 * the build through its environment. */
function nativeJson(ctx) {
  const settings = ctx.settings || {};
  const text = (name) => String(settings[name] ?? "").trim();
  const icon = text("app_icon");
  const buildType = text("build_type") || DEFAULT_BUILD_TYPE;
  // Its own keystore signs a release build only; the password is not here.
  const keystore = text("keystore_file");
  const signing =
    buildType === "release" && text("own_keystore") === "true"
      ? {
          keystore: keystore
            ? projectRelative(ctx, keystore) ?? keystore
            : null,
          alias: text("keystore_alias"),
        }
      : null;
  const appId = appIdFor(ctx);
  const profileSource = text("ios_profile_source") || "own";
  // An uploaded profile is the `own` source's only; a generated one is made
  // at build time and never named here.
  const profile = profileSource === "own" ? text("ios_profile") : "";
  return `${JSON.stringify(
    {
      appId,
      version: text("app_version") || DEFAULT_VERSION,
      icon: icon ? projectRelative(ctx, icon) ?? icon : null,
      buildType,
      signing,
      // A device build reads its bundle ID out of the profile; `bundleId` is
      // the App ID as iOS spells it, for a profile that has none (a wildcard),
      // for a generated profile, and for the simulator.
      ios: {
        profileSource,
        profile: profile ? projectRelative(ctx, profile) ?? profile : null,
        bundleId: iosBundleId(appId),
        simulatorConfiguration: text("simulator_configuration") || "release",
      },
    },
    null,
    2
  )}\n`;
}

/** Expo's app configuration, as code so it can read what Saltcorn generates.
 * The App ID, version and icon (the application's own settings) and each
 * platform's build settings come from `native.json`, and are checked when
 * `expo prebuild` writes a native project — not on the web export, which reads
 * this file too — so a bad one fails that build with a sentence rather than
 * Gradle's or Xcode's.
 * `web.output: "single"` is an SPA — one `index.html` Saltcorn's fallback
 * serves for every path. Written once: the project's to change. */
function appConfigJs(ctx) {
  const cleartextPlugin = cleartext(ctx)
    ? `\n        ["expo-build-properties", { android: { usesCleartextTraffic: true } }],`
    : "";
  const atsPlist = cleartext(ctx)
    ? `\n    infoPlist: { NSAppTransportSecurity: { NSAllowsArbitraryLoads: true } },`
    : "";
  return `// Expo's configuration. The App ID, version and icon, and the Android and
// iOS build settings, come from the application's settings in Saltcorn, which
// every build writes into ${ctx.runtime}/native.json.
const fs = require("fs");
const path = require("path");
const {
  withAppBuildGradle,
  withGradleProperties,
  withXcodeProject,
} = require("expo/config-plugins");

const native = JSON.parse(fs.readFileSync(path.join(__dirname, ${JSON.stringify(
    `${ctx.runtime}/native.json`
  )}), "utf8"));
const ios = require(path.join(__dirname, ${JSON.stringify(
    `${ctx.runtime}/ios/prebuild.cjs`
  )}));

// A device build is signed from its provisioning profile, which also decides
// its bundle ID; null for every other build that loads this file.
const iosSigning = ios.prebuildSigning(__dirname, native);
const bundleIdentifier = iosSigning ? iosSigning.bundleId : (native.ios || {}).bundleId;

// Android installs an update only over a lower versionCode, so it follows the
// version: 1.2.3 is 1002003.
const version = /^(\\d{1,3})\\.(\\d{1,3})\\.(\\d{1,3})$/.exec(native.version || "");
const versionCode = version
  ? Number(version[1]) * 1000000 + Number(version[2]) * 1000 + Number(version[3])
  : undefined;
const iconExists = Boolean(native.icon) && fs.existsSync(path.join(__dirname, native.icon));

/** The Android settings, checked when \`expo prebuild\` writes the Android
 * project, so a bad one fails the APK build with a sentence rather than
 * Gradle's — and never the web export, which evaluates this file too. */
function checkAndroid() {
  if (!/^[a-zA-Z][a-zA-Z0-9_]*(\\.[a-zA-Z][a-zA-Z0-9_]*)+$/.test(native.appId)) {
    throw new Error(
      \`The application ID "\${native.appId}" is not a Java package name: two or more dot-separated \` +
        "segments of letters, digits and _, each starting with a letter (com.example.todo).",
    );
  }
  if (!version) {
    throw new Error(\`The version "\${native.version}" is not major.minor.patch, e.g. 1.2.3.\`);
  }
  if (versionCode === 0) {
    throw new Error("The version 0.0.0 cannot be installed; use 0.0.1 or later.");
  }
  if (native.icon) {
    if (!/\\.(png|jpe?g)$/i.test(native.icon)) {
      throw new Error(\`The icon "\${native.icon}" is not a PNG or JPEG, which Android needs.\`);
    }
    if (!iconExists) {
      throw new Error(\`The icon "\${native.icon}" does not exist (relative to the project).\`);
    }
  }
  if (native.signing) {
    const { keystore, alias } = native.signing;
    if (!keystore || !fs.existsSync(path.join(__dirname, keystore))) {
      throw new Error(\`The keystore "\${keystore || ""}" does not exist (relative to the project).\`);
    }
    if (!alias) throw new Error("Signing with your own keystore needs the key's alias.");
    if (!process.env.FELDSPAR_KEYSTORE_PASSWORD) {
      throw new Error(
        "Signing with your own keystore needs its password; set it in the application's " +
          "Android app settings and build from Saltcorn.",
      );
    }
  }
}

/** A Groovy string literal: single-quoted, so a \`$\` in it is not interpolated. */
const groovy = (text) => \`'\${String(text).replace(/\\\\/g, "\\\\\\\\").replace(/'/g, "\\\\'")}'\`;

/** What \`app/build.gradle\` needs beyond Expo's: a debug build that carries its
 * JavaScript bundle (as a release one does, so it runs without a Metro dev
 * server beside the phone), and a release build signed with the application's
 * own keystore. The password is read from the build's environment, so it is
 * never written into the project. */
const withAndroidBuild = (config) =>
  withAppBuildGradle(config, (mod) => {
    checkAndroid();
    let gradle = mod.modResults.contents;
    if (native.buildType === "debug" && !gradle.includes("debuggableVariants = []")) {
      gradle = gradle.replace(/react\\s*\\{/, (open) => \`\${open}\\n    debuggableVariants = []\`);
    }
    if (native.buildType === "release" && native.signing && !gradle.includes("FELDSPAR_KEYSTORE_PASSWORD")) {
      const keystore = path.resolve(__dirname, native.signing.keystore);
      gradle = gradle.replace(
        /signingConfigs\\s*\\{/,
        (open) =>
          \`\${open}\\n        release {\\n\` +
          \`            storeFile file(\${groovy(keystore)})\\n\` +
          \`            storePassword System.getenv("FELDSPAR_KEYSTORE_PASSWORD")\\n\` +
          \`            keyAlias \${groovy(native.signing.alias)}\\n\` +
          \`            keyPassword System.getenv("FELDSPAR_KEYSTORE_PASSWORD")\\n\` +
          \`        }\`,
      );
      gradle = gradle.replace(
        /(buildTypes\\s*\\{[\\s\\S]*?release\\s*\\{[\\s\\S]*?)signingConfig signingConfigs\\.debug/,
        "$1signingConfig signingConfigs.release",
      );
    }
    mod.modResults.contents = gradle;
    return mod;
  });

/** Native code for 64-bit devices only: \`arm64-v8a\` (nearly every phone) and
 * \`x86_64\` (an emulator on a PC). Each architecture adds 20–30 MB to the APK,
 * and the 32-bit ones (\`armeabi-v7a\`, \`x86\`) are for devices too old to matter. */
const ARCHITECTURES = "arm64-v8a,x86_64";
/** What the iOS project needs beyond Expo's: the settings checked, and a device
 * build's signing from its provisioning profile (\`${
   ctx.runtime
 }/ios/prebuild.cjs\`). */
const withIos = (config) =>
  withXcodeProject(config, (mod) => {
    ios.checkConfig(__dirname, native, bundleIdentifier);
    if (iosSigning) ios.applySigning(mod.modResults, iosSigning);
    return mod;
  });

const withArchitectures = (config) =>
  withGradleProperties(config, (mod) => {
    mod.modResults = mod.modResults.filter(
      (item) => !(item.type === "property" && item.key === "reactNativeArchitectures"),
    );
    mod.modResults.push({ type: "property", key: "reactNativeArchitectures", value: ARCHITECTURES });
    return mod;
  });

module.exports = () =>
  withIos(withArchitectures(
    withAndroidBuild({
      name: ${JSON.stringify(ctx.app.name)},
      slug: ${JSON.stringify(ctx.name)},
      version: native.version,
      orientation: "portrait",
      userInterfaceStyle: "light",
      ...(iconExists ? { icon: native.icon } : {}),
      android: { package: native.appId, ...(versionCode ? { versionCode } : {}) },
      // The build number follows the version as the versionCode does.
      ios: {
        bundleIdentifier,
        supportsTablet: true,
        ...(versionCode ? { buildNumber: String(versionCode) } : {}),${atsPlist}
      },
      web: { output: "single", bundler: "metro" },
      plugins: [${cleartextPlugin}
      ],
    }),
  ));
`;
}

/** The iOS build code, real JavaScript files in this module, copied into the
 * project's runtime directory on every build so fixes reach existing projects.
 *
 * Two entry points:
 * - `ios/build.cjs`: the `build:ios:*` scripts (prebuild, pods, xcodebuild, export).
 * - `ios/prebuild.cjs`: what `app.config.js` needs during `expo prebuild`
 *   (checks, and signing on the app target only; the Pods are left alone).
 *
 * And what they use:
 * - `ios/signing.cjs`: reading the profile, shared by both. Like Saltcorn 1,
 *   the provisioning profile provides the team, bundle ID and certificates,
 *   and the keychain must hold one of those certificates with its private key.
 * - `ios/profile-generator.cjs`: generating a profile via the App Store Connect API. */
const IOS_FILES = [
  "ios/build.cjs",
  "ios/prebuild.cjs",
  "ios/signing.cjs",
  "ios/profile-generator.cjs",
].map((name) => ({
  name,
  text: ownFileText(name),
}));

/** Expo's base settings (it knows what Metro and React Native expect), with the
 * strictness every generated project here has. `tsc --noEmit` runs before the
 * web export on purpose: the client is regenerated from the app's endpoints on
 * every build, so a removed table fails the build naming the call site. */
const TSCONFIG = `{
  "extends": "expo/tsconfig.base",
  "compilerOptions": {
    "strict": true,
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "skipLibCheck": true
  },
  "include": ["index.ts", "src"]
}
`;

/** The generated runtime is part of the source; `/android` and `/ios` are what
 * `expo prebuild` writes (anchored, so the runtime's own `ios/` stays in git), and are rewritten from `app.config.js` on every target
 * build; `android-output/` and `ios-output/` are where each build leaves its
 * APK or AAB, and its IPA or zipped simulator app;
 * `build-logs/` is where the server writes each target build's log. The last lines are the session files `feldspar auth token` writes. */
const GITIGNORE = `node_modules
dist
.expo
/android
/ios
android-output
ios-output
build-logs
*.local
.feldspar-session
.feldspar-session.json
`;

/** The entry point on every platform: Expo registers the root component with
 * `AppRegistry` and, on the web, mounts it into its own `#root`. */
const INDEX_TS = `import { registerRootComponent } from "expo";

import Root from "./src/Root";

registerRootComponent(Root);
`;

/** The providers around the shell. */
function rootTsx(ctx) {
  const imports = [
    `import App from "./App";`,
    ...(ctx.auth ? [`import { AuthProvider } from "./auth";`] : []),
    `import { NavigationProvider } from "./navigation";`,
  ].join("\n");
  const app = ctx.auth
    ? `      <AuthProvider>
        <App />
      </AuthProvider>`
    : `      <App />`;
  return `${imports}

export default function Root() {
  return (
    <NavigationProvider>
${app}
    </NavigationProvider>
  );
}
`;
}

/** A navigator small enough to read: the current path in state, and — on the
 * web — kept in step with the address bar and the back button. On a phone it
 * has no back stack; React Navigation is the replacement when one is needed, and
 * the screens only ever call `navigate`. */
const NAVIGATION_TSX = `import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import { Platform } from "react-native";

export type Navigation = {
  /** The current path within the app. */
  path: string;
  navigate: (path: string) => void;
};

const NavigationContext = createContext<Navigation | undefined>(undefined);

const startPath = (): string => (Platform.OS === "web" ? window.location.pathname : "/");

export function NavigationProvider({ children }: { children: ReactNode }) {
  const [path, setPath] = useState(startPath);

  useEffect(() => {
    if (Platform.OS !== "web") return;
    const onPop = () => setPath(window.location.pathname);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const navigate = useCallback((next: string) => {
    if (Platform.OS === "web" && next !== window.location.pathname) {
      window.history.pushState(null, "", next);
    }
    setPath(next);
  }, []);

  return (
    <NavigationContext.Provider value={{ path, navigate }}>{children}</NavigationContext.Provider>
  );
}

export function useNavigation(): Navigation {
  const navigation = useContext(NavigationContext);
  if (!navigation) throw new Error("useNavigation must be used inside <NavigationProvider>");
  return navigation;
}
`;

